import{_ as t,c as s,o as a,ah as r,j as e,a as n}from"./chunks/framework.oAolcYhj.js";const d="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_edit_area.jpg",u="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_routing.jpg",h="/Qonnectra-docs/pr-14/videos/conduit_connection_routing.webm",c="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_linked_trenches.jpg",l="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_project_flag.jpg",g="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_conduit.jpg",m="/Qonnectra-docs/pr-14/videos/conduit_connection_map_selection.webm",p="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_list.jpg",b="/Qonnectra-docs/pr-14/videos/conduit_connection_map_find.webm",S=JSON.parse('{"title":"7. Rohrzuordnung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/07-rohrzuordnung.md","filePath":"manual/teil-a-anwenderhandbuch/07-rohrzuordnung.md"}'),_={name:"manual/teil-a-anwenderhandbuch/07-rohrzuordnung.md"};function z(k,i,f,w,v,T){return a(),s("div",null,[...i[0]||(i[0]=[r('<h1 id="_7-rohrzuordnung" tabindex="-1">7. Rohrzuordnung <a class="header-anchor" href="#_7-rohrzuordnung" aria-label="Permalink to &quot;7. Rohrzuordnung&quot;">​</a></h1><p>Die <strong>Rohrzuordnung</strong> ordnet Rohre den <strong>Trassensegmenten</strong> zu, in denen sie liegen. Sie erreichen sie über die linke Navigation in der Gruppe „Rohr“ durch Klicken auf den Menüpunkt „Zuordnung“.</p><p><img src="'+d+'" alt="Screenshot Rohrzuordnung mit der Karte links und dem Arbeitsbereich rechts" data-zoomable="true"></p><p>Der Bildschirm ist zweigeteilt: links die Karte, rechts der Arbeitsbereich.</p><h2 id="_7-1-grundprinzip" tabindex="-1">7.1 Grundprinzip <a class="header-anchor" href="#_7-1-grundprinzip" aria-label="Permalink to &quot;7.1 Grundprinzip&quot;">​</a></h2><p>Die Zuordnung geschieht in der Karte: Sie wählen rechts ein Rohr aus und klicken links das Trassensegment an, in dem es liegt. Ein <strong>Trassensegment</strong> ist ein einzelnes Objekt des Layers „Trasse“ und trägt eine eigene Trassen-ID.</p><p>Anklickbar sind ausschließlich die Segmente dieses Layers. Adressen, Netzknoten und Gebiete zeichnet die Karte zwar mit, sie dienen hier aber nur der Orientierung – eine Info-Box wie in der Karte (siehe Kapitel <a href="./05-karte.html">Karte</a>) öffnet sich nicht.</p><p>Solange kein Rohr ausgewählt ist, bleiben Klicks in die Karte ohne Wirkung; ein Hinweis am unteren Rand der Karte fordert zur Auswahl auf. Klicken Sie trotzdem hinein, erscheint die Meldung „Kein Rohr ausgewählt“.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Es gibt keinen „Speichern“-Button. Jede Zuordnung ist mit dem Klick gespeichert und lässt sich nur durch Löschen wieder aufheben, siehe Abschnitt <a href="#_7-3-4-loschen-einer-zuordnung">Löschen einer Zuordnung</a>.</p></div><h2 id="_7-2-kartennavigation-und-arbeitsbereich" tabindex="-1">7.2 Kartennavigation und Arbeitsbereich <a class="header-anchor" href="#_7-2-kartennavigation-und-arbeitsbereich" aria-label="Permalink to &quot;7.2 Kartennavigation und Arbeitsbereich&quot;">​</a></h2><p>Die Karte verhält sich wie unter dem Menüpunkt „Karte“, siehe Kapitel <a href="./05-karte.html">Karte</a>.</p><p>Rechts daneben liegt der Arbeitsbereich, von oben nach unten: die Umschalter „Routing-Modus“ und „Trassenverbindungen anzeigen“, die Felder „Kennzeichen“ und „Rohr“ und darunter die Liste der zugeordneten Trassensegmente.</p><p><img src="'+o+'" alt="Screenshot Rohrzuordnung mit Hervorhebung des Arbeitsbereichs rechts neben der Karte" data-zoomable="true"></p><h3 id="_7-2-1-routing-modus" tabindex="-1">7.2.1 Routing-Modus <a class="header-anchor" href="#_7-2-1-routing-modus" aria-label="Permalink to &quot;7.2.1 Routing-Modus&quot;">​</a></h3><p>Der <strong>Routing-Modus</strong> bestimmt, wie viele Trassensegmente ein Klick in die Karte zuordnet.</p><ul><li>Routing-Modus <strong>ausgeschaltet</strong>: Jeder Klick ordnet genau das angeklickte Trassensegment zu.</li><li>Routing-Modus <strong>eingeschaltet</strong>: Der erste Klick setzt den Start-, der zweite den Endpunkt. Qonnectra berechnet den kürzesten Weg zwischen beiden und ordnet alle Trassensegmente auf diesem Weg auf einmal zu.</li></ul><p><img src="'+u+'" alt="Screenshot Rohrzuordnung mit Hervorhebung des Umschalters „Routing-Modus“ oben im Arbeitsbereich" data-zoomable="true"></p>',17),e("p",null,[e("video",{src:h,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/conduit_connection_routing.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),r('<p>Ein dritter Klick verwirft die berechnete Route und setzt einen neuen Startpunkt; dasselbe bewirkt das Aus- und Wiedereinschalten des Routing-Modus. Verworfen wird dabei nur die Auswahl in der Karte – was bereits zugeordnet ist, bleibt in der Liste.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Start- und Endpunkt müssen im Trassennetz miteinander verbunden sein. Findet Qonnectra keinen Weg, meldet es „Fehler beim Berechnen der Route“, und es wird nichts zugeordnet. Wie groß der Abstand zwischen zwei Segmenten dabei sein darf, legt die „Routing-Toleranz“ unter „Einstellungen“ im Abschnitt „Rohrzuordnung“ fest.</p></div><h3 id="_7-2-2-trassenverbindungen-anzeigen" tabindex="-1">7.2.2 Trassenverbindungen anzeigen <a class="header-anchor" href="#_7-2-2-trassenverbindungen-anzeigen" aria-label="Permalink to &quot;7.2.2 Trassenverbindungen anzeigen&quot;">​</a></h3><p>Der Umschalter „Trassenverbindungen anzeigen“ hebt die Trassensegmente, die dem ausgewählten Rohr bereits zugeordnet sind, in der Karte farbig hervor. So sehen Sie, welchen Weg das Rohr im Netz nimmt und an welcher Stelle noch eine Zuordnung fehlt.</p><p><img src="'+c+'" alt="Screenshot Rohrzuordnung mit Hervorhebung des Umschalters „Trassenverbindungen anzeigen“ oben im Arbeitsbereich und der hervorgehobenen Trassensegmente in der Kartenmitte" data-zoomable="true"></p><p>Ohne ausgewähltes Rohr bleibt der Umschalter wirkungslos.</p><h2 id="_7-3-zuordnung-von-rohren-zu-trassensegmenten" tabindex="-1">7.3 Zuordnung von Rohren zu Trassensegmenten <a class="header-anchor" href="#_7-3-zuordnung-von-rohren-zu-trassensegmenten" aria-label="Permalink to &quot;7.3 Zuordnung von Rohren zu Trassensegmenten&quot;">​</a></h2><p>Die Arbeit besteht aus zwei Schritten: erst das Rohr auswählen, dann die Trassensegmente in der Karte anklicken, in denen es liegt.</p><h3 id="_7-3-1-auswahl-von-rohren" tabindex="-1">7.3.1 Auswahl von Rohren <a class="header-anchor" href="#_7-3-1-auswahl-von-rohren" aria-label="Permalink to &quot;7.3.1 Auswahl von Rohren&quot;">​</a></h3><p>Zur Auswahl stehen die Rohre des Projekts, das oben links in der Kopfzeile ausgewählt ist – eingegrenzt auf das Kennzeichen im gleichnamigen Feld.</p><p><img src="'+l+'" alt="Screenshot Rohrzuordnung mit Hervorhebung der Projektauswahl in der Kopfzeile und des Feldes „Kennzeichen“ im Arbeitsbereich" data-zoomable="true"></p><p>Die Rohre stehen in der Liste mit ihrem Rohrtyp in Klammern, etwa „St-VL-02 (7x16/12)“ – anders als in der Rohrverwaltung, die Name und Rohrtyp in getrennten Spalten führt.</p><p><img src="'+g+'" alt="Screenshot Rohrzuordnung mit Hervorhebung des Feldes „Rohr“ und der geöffneten Rohrliste im Arbeitsbereich" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Wechseln Sie das Kennzeichen, wird die Rohrauswahl zurückgesetzt. Gibt es zu Projekt und Kennzeichen kein Rohr, meldet das Feld „Keine Rohre gefunden“.</p></div><p>Mit der Auswahl füllt sich die Liste darunter mit den Trassensegmenten, die dem Rohr bereits zugeordnet sind.</p><h3 id="_7-3-2-trassensegmente-zuordnen" tabindex="-1">7.3.2 Trassensegmente zuordnen <a class="header-anchor" href="#_7-3-2-trassensegmente-zuordnen" aria-label="Permalink to &quot;7.3.2 Trassensegmente zuordnen&quot;">​</a></h3><p>Klicken Sie in der Karte auf das Trassensegment, in dem das ausgewählte Rohr liegt. Achten Sie darauf, dass der Layer „Trasse“ in der Legende eingeschaltet ist und dass der Routing-Modus so steht, wie Sie ihn brauchen, siehe Abschnitt <a href="#_7-2-1-routing-modus">Routing-Modus</a>.</p><p>Nach der Zuordnung erscheint kurz die Meldung „Trassenverbindung gespeichert“, und das Segment steht in der Liste.</p>',18),e("p",null,[e("video",{src:m,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/conduit_connection_map_selection.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),r('<div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein Trassensegment kann mehrere Rohre führen; dasselbe Segment taucht deshalb bei mehreren Rohren in der Liste auf. Klicken Sie ein Segment an, das dem Rohr schon zugeordnet ist, meldet Qonnectra „Keine neuen Trassenverbindungen“ und ändert nichts.</p></div><h3 id="_7-3-3-zugeordnete-trassensegmente-finden" tabindex="-1">7.3.3 Zugeordnete Trassensegmente finden <a class="header-anchor" href="#_7-3-3-zugeordnete-trassensegmente-finden" aria-label="Permalink to &quot;7.3.3 Zugeordnete Trassensegmente finden&quot;">​</a></h3><p>Die Liste führt die Trassen-IDs der zugeordneten Segmente auf. Ein Klick auf die Spaltenüberschrift „Trassen-ID“ kehrt die Sortierung um, das Suchfeld darüber grenzt die Liste ein; beides bezieht sich auf alle Einträge, nicht nur auf die angezeigte Seite. Eine Seite umfasst zehn Einträge; darunter stehen die Gesamtzahl und die Seitenauswahl.</p><p><img src="'+p+'" alt="Screenshot Rohrzuordnung mit Hervorhebung der Liste der zugeordneten Trassensegmente samt Suchfeld und Seitenauswahl im Arbeitsbereich" data-zoomable="true"></p><p>Ein Klick auf eine Zeile zoomt die Karte auf das Segment und hebt es kurz blinkend hervor.</p>',5),e("p",null,[e("video",{src:b,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/conduit_connection_map_find.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),r('<p>Um Liste und Karte abzugleichen, schalten Sie in der Legende die Beschriftungen des Layers „Trasse“ ein: Die Karte zeigt dann die Trassen-IDs an, die in der Liste stehen.</p><h3 id="_7-3-4-loschen-einer-zuordnung" tabindex="-1">7.3.4 Löschen einer Zuordnung <a class="header-anchor" href="#_7-3-4-loschen-einer-zuordnung" aria-label="Permalink to &quot;7.3.4 Löschen einer Zuordnung&quot;">​</a></h3><p>Über das Papierkorb-Symbol am rechten Rand einer Zeile heben Sie eine Zuordnung wieder auf. Gelöscht wird dabei nur die Verbindung zwischen Rohr und Trassensegment – beide selbst bleiben erhalten.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Das Löschen erfolgt ohne Rückfrage: Der Eintrag verschwindet mit dem Klick, und rückgängig machen lässt sich das nicht.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Löschen setzt die Zugriffsstufe „Vollzugriff“ voraus; die Berechtigung zum Bearbeiten genügt dafür nicht. Fehlt sie, erscheint „Fehler beim Löschen der Trassenverbindung“, und die Zuordnung bleibt bestehen. Wenden Sie sich in diesem Fall an Ihre Administration.</p></div>',5)])])}const K=t(_,[["render",z]]);export{S as __pageData,K as default};
